import { test, expect, mock } from "bun:test";
test("toBe obj", () => { expect({ a: 1 }).toBe({ a: 1 }); });
test("toBe str", () => { expect("abc").toBe("abd"); });
test("not.toBe", () => { expect(1).not.toBe(1); });
test("toEqual arr", () => { expect([1, 2, 3]).toEqual([1, 2, 4]); });
test("toEqual str", () => { expect("a\nb").toEqual("a\nc"); });
test("not.toEqual", () => { expect({ a: 1 }).not.toEqual({ a: 1 }); });
test("toStrictEqual", () => { expect({ a: undefined }).toStrictEqual({}); });
test("truthy", () => { expect(0).toBeTruthy(); });
test("falsy", () => { expect(1).toBeFalsy(); });
test("null", () => { expect(1).toBeNull(); });
test("undef", () => { expect(1).toBeUndefined(); });
test("defined", () => { expect(undefined).toBeDefined(); });
test("nan", () => { expect(1).toBeNaN(); });
test("gt", () => { expect(1).toBeGreaterThan(2); });
test("gte", () => { expect(1).toBeGreaterThanOrEqual(2); });
test("lt", () => { expect(3).toBeLessThan(2); });
test("lte", () => { expect(3).toBeLessThanOrEqual(2); });
test("close", () => { expect(0.1 + 0.2).toBeCloseTo(0.4); });
test("contain", () => { expect([1, 2]).toContain(3); });
test("contain str", () => { expect("hello").toContain("z"); });
test("containEqual", () => { expect([{ a: 1 }]).toContainEqual({ a: 2 }); });
test("length", () => { expect([1, 2]).toHaveLength(3); });
test("property", () => { expect({ a: { b: 1 } }).toHaveProperty("a.c"); });
test("property val", () => { expect({ a: { b: 1 } }).toHaveProperty("a.b", 2); });
test("match", () => { expect("hello").toMatch(/z/); });
test("matchObject", () => { expect({ a: 1, b: 2 }).toMatchObject({ a: 2 }); });
test("instanceOf", () => { expect([]).toBeInstanceOf(Map); });
test("typeOf", () => { expect(1).toBeTypeOf("string"); });
test("not.toBeNull", () => { expect(null).not.toBeNull(); });
test("order", () => { expect({ b: 1, a: { d: 1, c: 2 } }).toEqual({ b: 1, a: { d: 1, c: 3 } }); });
test("asym", () => { expect({ a: 1, b: "hello", c: [1], d: 2 }).toEqual({ a: expect.any(Number), b: expect.stringContaining("ell"), c: expect.arrayContaining([1]), d: expect.anything(), e: expect.objectContaining({ x: 1 }), f: expect.stringMatching(/a/), g: expect.any(String) }); });
test("asym top", () => { expect(1).toEqual(expect.any(String)); });
test("not asym", () => { expect("a").not.toEqual(expect.anything()); });
test("asym str", () => { expect("abc").toEqual(expect.stringContaining("z")); });
